def find(p, x):
    while p[x] != x:
        p[x] = p[p[x]]; x = p[x]
    return x

def union(p, rk, a, b):
    ra, rb = find(p, a), find(p, b)
    if ra == rb:
        return False
    if rk[ra] < rk[rb]:
        ra, rb = rb, ra
    p[rb] = ra
    if rk[ra] == rk[rb]:
        rk[ra] += 1
    return True

print(union([0, 1, 2], [0, 0, 0], 0, 1))   # True

